CREATE TYPE public.app_role AS ENUM ('admin');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid, public.app_role) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.has_role(uuid, public.app_role) TO authenticated;
CREATE POLICY own_roles ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.news (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title jsonb NOT NULL DEFAULT '{}'::jsonb, body jsonb NOT NULL DEFAULT '{}'::jsonb, news_date date NOT NULL DEFAULT CURRENT_DATE, image_path text, published boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.news TO anon;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.news TO authenticated;
GRANT ALL ON public.news TO service_role;
ALTER TABLE public.news ENABLE ROW LEVEL SECURITY;
CREATE POLICY published_news ON public.news FOR SELECT TO anon, authenticated USING(published=true);
CREATE POLICY editor_read ON public.news FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE POLICY editor_insert ON public.news FOR INSERT TO authenticated WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE POLICY editor_update ON public.news FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE POLICY editor_delete ON public.news FOR DELETE TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE POLICY news_image_read ON storage.objects FOR SELECT TO anon,authenticated USING(bucket_id='news-images');
CREATE POLICY news_image_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='news-images' AND public.has_role(auth.uid(),'admin'));
CREATE POLICY news_image_update ON storage.objects FOR UPDATE TO authenticated USING(bucket_id='news-images' AND public.has_role(auth.uid(),'admin')) WITH CHECK(bucket_id='news-images' AND public.has_role(auth.uid(),'admin'));
CREATE POLICY news_image_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='news-images' AND public.has_role(auth.uid(),'admin'));